var sections = document.querySelectorAll('[id^="color_name_"]');
var colors = [];
sections.forEach(function(sec) {
  var input = sec.querySelector('input');
  if (input) {
    var label = input.getAttribute('aria-labelledby');
    var announce = label ? document.getElementById(label) : null;
    if (announce) {
      var text = announce.textContent.trim().split(' ');
      colors.push(text[0]);
    }
  }
});
return colors;

